    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (3, 9) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for a, b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] in (3,9) and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            components.append(cells)
    # Remove only the 9 marker in a connected pattern if its surrounding pattern
    # is a solitary marker; preserve all other 9s.
    for cells in components:
        markers = [(r,c) for r,c in cells if grid[r][c] == 9]
        if len(markers) == 1:
            r,c = markers[0]
            out[r][c] = 0
